-- World seed matrix (test copy only; docs/PHASE5-M1.md §4 World, tools/world-seeds.sh). For every nation count in
-- CFG.nations, CFG.seeds Nation matches are started through lobby.start_match (plan on engine samples, blocking core,
-- start kits), then the rest of the map is generated by force and the real-tile check runs (scripts/world.lua). Each
-- match gets a new arena seed (nauvis seed + match number). Log lines "[rts] world seeds: ..." with LuaProfiler
-- durations (tools/world-seeds.sh turns them into the time checks), checks "[rts] autotest check world_...: PASS|FAIL"
-- and a final "[rts] autotest summary P/T".
local events = require("scripts.events")
local util = require("scripts.util")
local lobby = require("scripts.lobby")
local world = require("scripts.world")
local ai = require("scripts.ai.init")
local match = require("scripts.match")

local CFG = {seeds = 20, nations = {2, 3, 4}, world_size = nil, images = false} -- tools/world-seeds.sh rewrites this line

local function S() return storage.world_seeds end

local function check(name, ok, fmt, ...)
  local st = S()
  if ok then st.pass = st.pass + 1 else st.fail = st.fail + 1 end
  util.log("autotest check %s: %s %s", name, ok and "PASS" or "FAIL", string.format(fmt, ...))
end

events.on_init(function()
  storage.debug = storage.debug or {}
  storage.debug.autotest = false -- no AI autotest in this copy
  storage.world_seeds = {i = 0, step = "start", pass = 0, fail = 0, runs = {}}
end)

local function current()
  local st = S()
  local per = CFG.seeds
  local ni = math.floor(st.i / per) + 1
  return CFG.nations[ni], st.i % per + 1
end

events.on_nth_tick(1, function(e)
  local st = S()
  if not st or st.done or e.tick < 150 then return end
  world.write_images = CFG.images
  world.QA_COUNTS = true
  if st.step == "start" then
    local nations, k = current()
    if not nations then
      st.done = true
      util.log("world seeds: done, %d runs", st.i)
      util.log("autotest summary %d/%d%s", st.pass, st.pass + st.fail, st.fail == 0 and " (all passed)" or
        string.format(" (%d FAILED)", st.fail))
      return
    end
    local cfg = {opponents = nations - 1, difficulty = "normal", mode = "nation", world_size = CFG.world_size,
                 enemy_brain = "ai"}
    local prof = helpers.create_profiler()
    lobby.start_match(cfg, "world-seeds")
    prof.stop()
    for _, f in ipairs(match.ai_forces()) do ai.stop_force(f) end
    local W = storage.world
    st.cur = {nations = nations, k = k, seed = W.seed, size = W.size, tick = e.tick}
    log({"", string.format("[rts] world seeds: run %d nations %d seed %d size %d: start (plan + core + kits) ", st.i + 1,
      nations, W.seed, W.size), prof})
    st.step = "fill"
  elseif st.step == "fill" then
    local W = storage.world
    local surface = game.surfaces[W.surface]
    local prof = helpers.create_profiler()
    surface.request_to_generate_chunks({0, 0}, math.ceil(W.size / 64))
    surface.force_generate_chunk_requests()
    prof.stop()
    log({"", string.format("[rts] world seeds: run %d nations %d seed %d: forced fill ", st.i + 1, st.cur.nations,
      st.cur.seed), prof})
    st.step = "post"
  elseif st.step == "post" then
    local W = storage.world
    if not (W.checks and W.checks.post) then
      if e.tick - st.cur.tick > 60 * 60 then
        check("world_post_" .. (st.i + 1), false, "no real-tile check after 60 s (fill %d/%d)", W.fill.generated, W.fill.total)
        st.i, st.step = st.i + 1, "start"
      end
      return
    end
    local P = W.plan
    local V = P.validation
    local tag = string.format("n%d_s%d", st.cur.nations, st.cur.seed)
    check("world_connectivity_" .. tag, #V.conn_bad == 0 and #W.checks.post.bad == 0,
      "sampled %d/%d, real tiles %d/%d%s", V.conn_targets - #V.conn_bad, V.conn_targets,
      W.checks.post.targets - #W.checks.post.bad, W.checks.post.targets,
      #W.checks.post.bad > 0 and (": " .. table.concat(W.checks.post.bad, ", ")) or "")
    local kit_ok, worst = #W.checks.kit > 0, 0
    for _, kp in ipairs(W.checks.kit) do
      worst = math.max(worst, kp.dist)
      if not (kp.placed and kp.tiles > 0 and kp.amount == kp.total and kp.dist <= world.KIT_RADIUS) then kit_ok = false end
    end
    check("world_start_kit_" .. tag, kit_ok, "%d patches, farthest edge %.0f tiles from its spawn", #W.checks.kit, worst)
    check("world_spread_" .. tag, V.spread <= world.SPREAD_MAX, "spawn score spread %.3f, nearest-enemy path spread %.3f, attempt %d of %d",
      V.spread, V.enemy_spread, P.attempt, V.attempts)
    local unplaced = 0
    for _, f in ipairs(W.features) do if not f.placed then unplaced = unplaced + 1 end end
    local counts = W.tile_counts or {}
    util.log("world seeds: run %d nations %d seed %d: barriers %d, crossings %d, deposits %d, regions %d, sites %d, "
      .. "unplaced %d, tiles %s, scores %s", st.i + 1, st.cur.nations, st.cur.seed, #P.barriers, #P.crossings,
      #P.deposits, #P.regions, #P.sites, unplaced, serpent.line(counts), serpent.line(V.scores))
    st.i, st.step = st.i + 1, "start"
  end
end)
